"""Generate the copyable continuation prompt from the authoritative tracker."""
import argparse
import csv
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
TRACKER = ROOT / 'docs/06-delivery/experience-execution.csv'
OUTPUT = ROOT / 'docs/06-delivery/continue-academyos.md'


def execution_route(rows):
    """Choose only an explicit tracker priority, never the first unfinished ID."""
    if not rows:
        raise ValueError('Execution tracker is empty')
    allowed_states = {'current', 'queued', 'supporting', 'retained', 'checkpoint_passed'}
    lanes = {'baseline', 'primary', 'supporting'}
    seen = set()
    for row in rows:
        if row.get('execution_lane') not in lanes or row.get('execution_state') not in allowed_states:
            raise ValueError(f"Invalid execution routing for {row.get('work_id')}")
        order = row.get('execution_order', '')
        if not order.isdecimal():
            raise ValueError('Execution order must be a nonnegative integer')
        pair = (row['execution_lane'], int(order))
        if pair in seen or not row.get('dependency_gate', '').strip():
            raise ValueError('Duplicate lane/order or missing scoped dependency gate')
        seen.add(pair)
        if row['execution_lane'] == 'primary':
            if row['execution_state'] not in {'current', 'queued', 'checkpoint_passed'}:
                raise ValueError('Primary work needs a current, queued or checkpoint_passed route state')
        elif row['execution_state'] != {'baseline': 'retained', 'supporting': 'supporting'}[row['execution_lane']]:
            raise ValueError('Baseline/supporting route state does not match lane')
    primary = sorted((r for r in rows if r['execution_lane'] == 'primary'), key=lambda r: int(r['execution_order']))
    if [int(r['execution_order']) for r in primary] != list(range(1, len(primary) + 1)):
        raise ValueError('Primary execution order must be consecutive from 1')
    current = [r for r in rows if r['execution_state'] == 'current']
    if len(current) != 1 or current[0]['execution_lane'] != 'primary':
        raise ValueError('Exactly one primary work item must be explicitly current')
    active = current[0]
    for row in primary:
        before = int(row['execution_order']) < int(active['execution_order'])
        if before and row['execution_state'] != 'checkpoint_passed':
            raise ValueError('Earlier primary checkpoint is not explicitly passed; record any reprioritization')
        if not before and row is not active and row['execution_state'] != 'queued':
            raise ValueError('Later primary work must remain queued')
    return active, primary


def render(rows):
    active, primary = execution_route(rows)
    intro = """# AcademyOS continuation prompt

Generated from `experience-execution.csv`, including its explicit execution lane/order/current state. Do not edit this file directly. Regenerate after every checkpoint with `python3 scripts/design/build_continuation_prompt.py`; the execution validator rejects stale or ambiguous routing. This is a continuation instruction, not new business policy, access authorization or evidence of acceptance.

Reusable instruction: **Continue from the living continuation prompt.**

---

Continue AcademyOS in `/Users/moamenghareeb/AcademyOS`.

Read `AGENTS.md`, `docs/06-delivery/local-data-and-sync-plan.md`, `docs/04-engineering/offline-edit-and-conflict-contract.md`, `docs/04-engineering/shift-ios-local-data-reference-review.md`, `docs/06-delivery/experience-execution.md`, `docs/06-delivery/experience-execution.csv`, `docs/03-design/academy-working-behavior-contract.md`, `docs/06-delivery/academy-working-day-acceptance.md` and the evidence linked by the current row. Recheck working tree, actual source and release. Preserve completed work and concurrent changes.

Start with the explicit current priority below, not the first unfinished EX number or an old next-step sentence in a historical packet. Follow its current next action and scoped dependency gate. Keep the retained baseline and all supporting/open work visible. Advance routing only after recording the declared checkpoint evidence; a routing checkpoint is not whole-finding closure or Owner/security acceptance.

The Owner clarified the operating goal: persistent permitted local datasets across visits, progressive player-directory/month or three-month preparation and quiet synchronization, plus new offline edits saved locally and synchronized on reconnect. First task essentials → finite resumable dataset pages → transactional local coverage → later compatible local reopening → small access/version checks → changed data/removals. Do not substitute a tab-memory-only summary cache, colour pass or new feature. Finite all-permitted directory/period preparation is different from unbounded whole-app/database preloading; complete disk coverage does not mean all records in memory. Code preparation, local read replicas, query memory, drafts and immutable pending operations are distinct.

Preserve current server authority, tenant/role/field scope, explicit context choice, dirty input, exact-change/signed review, atomic/idempotent writes and original unknown-operation recovery. The connected read/preparation design is approved. No inactivity lock or proposed24hour local-read cutoff;30day-without-verification/logout read-replica cleanup is selected. Do not re-ask those decisions or apply replica cleanup to unresolved original operations/unsent offline edits. WB-P01–P04's unaccepted summary-only/30second/5minute/intent-only proposal is superseded. LF-P01–LF-P06 own remaining exact device/unlock/fields/key/sync and sensitive-domain choices. Offline edits are now a target, not permanently future scope. The first Owner-register atomic/original-ID/current-server-check/Needs review policy is accepted for design, and protected pending-work recovery after logout/30day replica cleanup is selected. Do not re-ask those choices. The focused Owner offline-register changed-state design is now approved for implementation3November; do not re-ask it. Preserve the completed automatic-key mechanism, canonical replay/fence proof and workspace compatibility checkpoints; do not repeat them by default. The inactive typed Owner-register adapter checkpoint now has38actual browser cases and is retained. Continue with coherent server transfer/authority contracts before actual bootstrap; real authenticated key custody, private field/time recovery and server transport gates remain required before private enablement. Do not repeat the completed library build or mistake per-row transfer completeness for a coherent server snapshot. Remaining device/field/key engineering and security readiness stay separate. After successful device/passkey research, the Owner rejected mandatory passkey setup/reopening and directs ordinary email/password sign-in for personal-device use. Do not re-ask that rejected choice or add a separate local secret. Follow the revised offline-register-device-key-contract.md for automatic protection and same-account recovery; do not persist the login password, use it/token as a key, or silently weaken confidentiality. Historical PRF results and failed-UV cases remain evidence, not prerequisites for the different mechanism. No real credential creation or provider-account change is included in ordinary continuation. The Owner suggested timestamps; engineering recommends expected server versions plus immutable IDs and retained conflicts, never silent device-clock overwrite. Current online writers remain unchanged until their domain slice is accepted and implemented. Finance, telemetry, real data and access grants remain separate; independent safe work continues.

Use actual AcademyOS source, PYSA workflow/audit and Shift staging iOS local-data reference plus the working-day case map. Reference code/tests are not AcademyOS operating proof. Record current versus target, repository/index/key/coverage/sync/authority/draft/recovery owners, first-bootstrap/reopen/unchanged/changed/save budgets and affected-view invalidation. Prove transactional checkpoints/watermarks, tombstones/withdrawal/scope epochs, cursor expiry, multi-tab leadership, key/quota/eviction/migration and original-operation recovery. Measure useful task readiness, blank intervals, local queries, input/context and API/RPC/SQL/bytes/costs alongside each batch. No zero-network/full-offline claim from a cached screen; closed-app background execution is not guaranteed. Keep EN/AR, phone/desktop/zoom and all-role limits explicit.

Promotion ownership: the Owner performs all deployment promotions. Prepare/test/push and inspect automatic builds as authorized, but never click Promote, invoke a CLI/connector promotion, reassign the live alias or complete the provider promotion/passkey flow. If needed, supply the exact checked commit/deployment link and existing staging destination for the Owner. Ordinary continuation is not an exception. Verify the Owner-reported result read-only and keep it separate from preview readiness.

After every checkpoint, update the tracker/evidence and affected plan/handoff, maintain actual-component factual HTML where required, regenerate this prompt and run the execution/canonical/review checks. Keep design, implementation, local tests, deployed source, hosted verification, Owner acceptance and independent security separate. If blocked, record the exact decision/evidence/access limitation and safe next action; do not invent approval or silently retire scope. No production launch, service purchase/upgrade or privileged access restoration is included.

"""
    current = '\n'.join([
        f"## Current priority — {active['work_id']}: {active['scope']}", '',
        f"Next action: {active['next_action']}", '',
        f"Scoped dependency gate: {active['dependency_gate']}", '',
        f"Read: `{active['evidence']}`", '',
        '## Ordered primary checkpoints', '',
        *[f"{r['execution_order']}. **{r['work_id']} — {r['scope']}** ({r['execution_state']})." for r in primary], '',
        'Supporting work runs with the affected checkpoint: ' + '; '.join(
            f"{r['work_id']} — {r['scope']}" for r in sorted(
                (r for r in rows if r['execution_lane'] == 'supporting'), key=lambda r: int(r['execution_order']))), '',
        'The order names checkpoint outputs, not a requirement to finish every role/future feature in a parent row before safe dependent work. Detailed gates remain in each row. Private policy choices block dependent behaviour only.', '',
        '## Tracker snapshot', '',
    ])
    fields = [('implementation_status', 'Implementation'), ('local_status', 'Local checks'),
              ('deployment_status', 'Deployment'), ('hosted_status', 'Hosted verification'),
              ('owner_acceptance_status', 'Owner acceptance'), ('independent_security_status', 'Independent security'),
              ('next_action', 'Next action'), ('evidence', 'Evidence')]
    rank = {'baseline': 0, 'primary': 1, 'supporting': 2}
    blocks = []
    for row in sorted(rows, key=lambda r: (rank[r['execution_lane']], int(r['execution_order']))):
        lines = [f"### {row['work_id']} — {row['scope']}", '',
                 f"Routing: {row['execution_lane']} / {row['execution_order']} / {row['execution_state']}.",
                 f"Dependencies: {row['dependencies'] or 'none declared'}.",
                 f"Dependency gate: {row['dependency_gate']}",
                 f"Findings: {row['finding_ids']}.", f"Design: {row['design_status']}.", '']
        lines += [f"- {label}: {row[key]}" for key, label in fields]
        blocks.append('\n'.join(lines))
    return intro + current + '\n' + '\n\n'.join(blocks) + '\n'


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    with TRACKER.open(newline='') as stream:
        expected = render(list(csv.DictReader(stream)))
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != expected:
            raise SystemExit('FAIL: continuation prompt stale; run python3 scripts/design/build_continuation_prompt.py')
        print('PASS: continuation prompt matches the execution tracker')
    else:
        OUTPUT.write_text(expected)
        print(f'Updated {OUTPUT.relative_to(ROOT)}')


if __name__ == '__main__':
    main()
